<?php require 'includes/layout.php';require_login();$s=db()->prepare('SELECT username,email,bio,created_at FROM users WHERE id=?');$s->execute([user()['id']]);$u=$s->fetch();$s=db()->prepare('SELECT COUNT(*) AS played,COALESCE(MAX(score),0) AS best,COALESCE(SUM(score),0) AS total FROM scores WHERE user_id=?');$s->execute([user()['id']]);$stats=$s->fetch();top('My Profile');?><div class="panel"><h2>👾 <?=e($u['username'])?></h2><p><?=e($u['email'])?></p><p><?=e($u['bio']?:'No bio yet.')?></p><p>Joined <?=e(date('M Y',strtotime($u['created_at'])))?></p><a class="btn" href="edit-profile.php">Edit profile</a></div><div class="grid2"><div class="stat"><strong><?=e($stats['played'])?></strong>Games played</div><div class="stat"><strong><?=e($stats['best'])?></strong>Best score</div><div class="stat"><strong><?=e($stats['total'])?></strong>Total points</div></div><?php bottom(); ?>